--
-- Name: companies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.companies (
    id text NOT NULL,
    name text NOT NULL,
    sector text NOT NULL,
    profile text NOT NULL,
    kpis jsonb NOT NULL,
    embedding public.vector(1024) NOT NULL,
    profile_tsv tsvector GENERATED ALWAYS AS (to_tsvector('portuguese'::regconfig, profile)) STORED
);


--
-- Data for Name: companies; Type: TABLE DATA; Schema: public; Owner: -
--



--
-- Name: companies companies_pkey; Type: CONSTRAINT; Schema: public; Owner: -
--

ALTER TABLE ONLY public.companies
    ADD CONSTRAINT companies_pkey PRIMARY KEY (id);


--
-- Name: companies_embedding_ivfflat; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX companies_embedding_ivfflat ON public.companies USING ivfflat (embedding public.vector_cosine_ops) WITH (lists='100');


--
-- Name: companies_profile_tsv_gin; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX companies_profile_tsv_gin ON public.companies USING gin (profile_tsv);


