--
-- accounts: login layer over companies (appended to the companies dump).
--
-- pg_dump sets an empty search_path and schema-qualifies everything as
-- public.*; re-select public so the unqualified statements below resolve.
SET search_path TO public;
DROP TABLE IF EXISTS accounts;
CREATE TABLE accounts (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  email         TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  company_cnpj  TEXT NOT NULL REFERENCES companies(id),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX accounts_email_idx ON accounts (email);


